public class InnerMemoryCustomConfigurationInputFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput>
{

    internal InnerMemorySummaryOverrideFactory SummaryOverrideFactory { get; set; }

    internal InnerMemoryUserPreferenceOverrideFactory UserPreferenceOverrideFactory { get; set; }

    internal InnerMemoryEpisodicOverrideFactory EpisodicOverrideFactory { get; set; }

    internal InnerMemorySemanticOverrideFactory SemanticOverrideFactory { get; set; }

    internal InnerMemorySelfManagedConfigurationFactory SelfManagedConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput Create()
    {
        var customConfigurationInputResult = CreateCustomConfigurationInput();
        factoryAction?.Invoke(customConfigurationInputResult);

        return customConfigurationInputResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput CreateCustomConfigurationInput()
    {
        var customConfigurationInputResult = new Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput();

        return customConfigurationInputResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.CustomConfigurationInput result)
    {
        base.CreateChildren(result);

        result.SummaryOverride ??= SummaryOverrideFactory?.Build();
        result.UserPreferenceOverride ??= UserPreferenceOverrideFactory?.Build();
        result.EpisodicOverride ??= EpisodicOverrideFactory?.Build();
        result.SemanticOverride ??= SemanticOverrideFactory?.Build();
        result.SelfManagedConfiguration ??= SelfManagedConfigurationFactory?.Build();
    }

} // End Of Class

